    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xB9257FED8906ECDDULL + 0x9F299D46BF8B43AEULL);
