            aOrbiterI = ((aWandererI + RotL64(aPrevious, 14U)) + RotL64(aCarry, 35U)) + 0xDC9D9B22424D77AAULL;
            aOrbiterC = ((aWandererE + RotL64(aScatter, 29U)) + RotL64(aCarry, 5U)) + 0xC622B65C228137CBULL;
