            aWandererC = aWandererC ^ (((RotL64(aIngress, 39U) + RotL64(aOrbiterG, 53U)) + aOrbiterE) + aTwistWandererUpdateSaltB[(((255U - aIndex) + 219U)) & S_SALT1]);
