            aWandererH = aWandererH + ((RotL64(aScatter, 57U) + RotL64(aOrbiterJ, 19U)) + aOrbiterH);
            aWandererG = aWandererG ^ (((RotL64(aCross, 43U) + aOrbiterB) + RotL64(aOrbiterH, 23U)) + aTwistWandererUpdateSaltD[(((255U - aIndex) + 164U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aPrevious, 48U) + aOrbiterE) + RotL64(aOrbiterD, 28U)) + RotL64(aCarry, 11U));
