            aOrbiterH = ((aWandererI + RotL64(aIngress, 30U)) + RotL64(aCarry, 57U)) + 0xD708F8411DF2E8D1ULL;
            aOrbiterI = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 5U)) + 0xAC6047B36827460EULL) + aKeyRotateBOrbiterAssignSaltD[((aIndex + 164U)) & S_SALT1];
